<template><div class="system-page"><div class="page-head"><div><h1>字段权限管理</h1><p>控制不同岗位是否可以查看利润、成本、手机号、工资等敏感字段。</p></div><el-button type="primary" @click="save">保存</el-button></div><div class="card toolbar"><el-select v-model="roleId" placeholder="选择角色" style="width:260px" @change="loadPerm"><el-option v-for="r in roles" :key="r.id" :label="r.name" :value="r.id"/></el-select><el-button @click="applyTpl('boss')">老板模板</el-button><el-button @click="applyTpl('finance')">财务模板</el-button><el-button @click="applyTpl('store')">店长模板</el-button><el-button @click="applyTpl('guide')">导购模板</el-button></div><div class="card"><el-table :data="matrix"><el-table-column prop="field_name" label="字段编码"/><el-table-column prop="field_label" label="字段名称"/><el-table-column prop="module" label="所属模块"/><el-table-column label="查看"><template #default="{row}"><el-switch v-model="row.can_view"/></template></el-table-column><el-table-column label="脱敏规则"><template #default="{row}"><el-select v-model="row.mask_rule"><el-option label="正常显示" value="none"/><el-option label="隐藏" value="hide"/><el-option label="脱敏" value="mask"/><el-option label="只看汇总" value="summary"/></el-select></template></el-table-column></el-table></div></div></template><script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{systemApi}from'@/api/system';const roles=ref<any[]>([]),roleId=ref<number>(),matrix=ref<any[]>([]);async function loadRoles(){const r=await systemApi.getRoles({show_legacy:false});roles.value=r.data.data||[];roleId.value=roles.value[0]?.id;loadPerm()}async function loadPerm(){if(!roleId.value)return;const r=await systemApi.getFieldPermissions({role_id:roleId.value});const saved=r.data.data.items||[];matrix.value=(r.data.data.resources||[]).map((x:any)=>({role_id:roleId.value,can_view:true,mask_rule:'none',...x,...(saved.find((s:any)=>s.field_name===x.field_name)||{})}))}function applyTpl(t:string){matrix.value.forEach((r:any)=>{r.can_view=true;r.mask_rule='none';if(t==='guide'&&/(profit|cost|salary|cash)/.test(r.field_name)){r.mask_rule='hide';r.can_view=false}if(t==='store'&&/(profit|cost)/.test(r.field_name))r.mask_rule='summary';if(t==='finance'&&/phone|salary/.test(r.field_name))r.mask_rule='mask'})}async function save(){await systemApi.updateFieldPermissions({role_id:roleId.value,items:matrix.value});ElMessage.success('字段权限已保存')}onMounted(loadRoles)</script>
<style scoped>.system-page{padding:24px;background:#f6f8fb;min-height:100%}.page-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.page-head h1{margin:0;color:#0f172a;font-size:26px}.page-head p{margin:8px 0 0;color:#64748b}.card{background:#fff;border:1px solid #e5eaf2;border-radius:8px;padding:18px;margin-bottom:16px;box-shadow:0 1px 2px rgba(15,23,42,.035)}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.stat{background:#fff;border:1px solid #e5eaf2;border-radius:8px;padding:18px}.stat b{font-size:28px;color:#0f172a}.stat span{display:block;color:#64748b;margin-top:6px}.layout2{display:grid;grid-template-columns:360px 1fr;gap:16px}.muted{color:#94a3b8;font-size:12px}.jsonbox{max-height:280px;overflow:auto;background:#f8fafc;color:#334155;border:1px solid #e5eaf2;padding:12px;border-radius:8px;font-size:12px;white-space:pre-wrap}@media(max-width:1100px){.layout2{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}
</style>
